import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"资源管理器","description":"","frontmatter":{},"headers":[],"relativePath":"resources/asset-manager.md","filePath":"resources/asset-manager.md","lastUpdated":null}'),s={name:"resources/asset-manager.md"};function n(d,t,l,i,g,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="资源管理器" tabindex="-1">资源管理器 <a class="header-anchor" href="#资源管理器" aria-label="Permalink to &quot;资源管理器&quot;">​</a></h1><h2 id="打开资源管理器" tabindex="-1">打开资源管理器 <a class="header-anchor" href="#打开资源管理器" aria-label="Permalink to &quot;打开资源管理器&quot;">​</a></h2><p>在 <strong>设置面板</strong> 中可以打开资源管理器，它是管理所有视觉资源的统一入口。</p><h2 id="资源分类" tabindex="-1">资源分类 <a class="header-anchor" href="#资源分类" aria-label="Permalink to &quot;资源分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>内容</th></tr></thead><tbody><tr><td><strong>立绘</strong></td><td>角色立绘图片（含表情差分）</td></tr><tr><td><strong>背景</strong></td><td>场景背景图片</td></tr><tr><td><strong>Live2D</strong></td><td>Live2D 模型文件</td></tr><tr><td><strong>地图</strong></td><td>地图背景图片</td></tr><tr><td><strong>图包</strong></td><td>资源图包（可打包多种资源）</td></tr><tr><td><strong>UI 皮肤</strong></td><td>界面主题皮肤</td></tr></tbody></table><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><p>每种资源都支持：</p><ul><li>📤 <strong>上传</strong> —— 添加新资源</li><li>👁️ <strong>预览</strong> —— 查看已有资源</li><li>🗑️ <strong>删除</strong> —— 移除不需要的资源</li><li>✏️ <strong>编辑</strong> —— 修改资源属性（名称、标签等）</li></ul><h2 id="图包系统" tabindex="-1">图包系统 <a class="header-anchor" href="#图包系统" aria-label="Permalink to &quot;图包系统&quot;">​</a></h2><p>图包是一组资源的集合，可以方便地打包和切换：</p><ul><li><strong>创建图包</strong>：将当前资源打包</li><li><strong>导入图包</strong>：从文件或远程地址导入</li><li><strong>切换图包</strong>：一键切换活跃的资源包</li><li><strong>远程图包</strong>：配置远程地址后，资源可从 CDN 按需加载</li></ul>',11)])])}const _=r(s,[["render",n]]);export{u as __pageData,_ as default};
